 "content": "from collections import deque


def transform(grid):
    """Extract the largest zero-masked rectangle and restore its vertical reflection."""
    h, w = len(grid), len(grid[0])
    unseen = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 0}
    components = []
    while unseen:
        start = unseen.pop()
        component = {start}
        queue = deque([start])
        while queue:
            r, c = queue.popleft()
            for nr, nc in ((r-1,c),(r+1,c),(r,c-1),(r,c+1)):
                if (nr, nc) in unseen:
                    unseen.remove((nr, nc))
                    component.add((nr, nc))
                    queue.append((nr, nc))
        components.append(component)
    if not components:
        raise ValueError("Expected a zero-masked rectangle")
    cells = max(components, key=len)
    r0, r1 = min(r for r, _ in cells), max(r for r, _ in cells)
    c0, c1 = min(c for _, c in cells), max(c for _, c in cells)
    if len(cells) != (r1-r0+1)*(c1-c0+1):
        raise ValueError("Largest zero component is not rectangular")
    return [[grid[h-1-r][c] for c in range(c0, c1+1)] for r in range(r0, r1+1)]


if __name__ == "__main__":
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
